"""SYNTHETIC test images. Generated by code; never astronomical observations.

SyntheticProduct implements the ProductLike protocol with a pure-NumPy linear
TAN WCS and a linear wavelength gradient along x (mimicking a linear variable
filter), so measurement code can be exercised without FITS files or network.
"""

from __future__ import annotations

import numpy as np

from skytrace.science.coords import gnomonic, inverse_gnomonic


class SyntheticProduct:
    SYNTHETIC = True

    def __init__(self, shape=(60, 60), crval=(180.0, 0.0), crpix=(29.5, 29.5), scale_arcsec=6.2,
                 rotation_deg=0.0, wl0_um=1.30, wl_slope_um_per_px=0.004, bw_um=0.03,
                 sky_mjysr=0.5, noise_mjysr=0.02, seed=0, flag_header=None):
        self.shape, self.crval, self.crpix = shape, crval, crpix
        s = scale_arcsec / 3600.0
        th = np.radians(rotation_deg)
        # x (column) increases to the west on the sky (east-left convention)
        self.cd = s * np.array([[-np.cos(th), np.sin(th)], [np.sin(th), np.cos(th)]])
        self.cd_inv = np.linalg.inv(self.cd)
        self.wl0, self.wls, self.bw = wl0_um, wl_slope_um_per_px, bw_um
        self.rng = np.random.default_rng(seed)
        self.noise = noise_mjysr
        self.image = np.full(shape, sky_mjysr, float)
        self.variance = np.full(shape, noise_mjysr ** 2, float)
        self.flags = np.zeros(shape, np.int32)
        self.headers = {"IMAGE": {"BUNIT": "MJy/sr"}, "FLAGS": flag_header or {}}
        self.scale_arcsec = scale_arcsec

    def sky_to_pixel(self, ra, dec):
        xi, eta = gnomonic(ra, dec, *self.crval)
        dx, dy = self.cd_inv @ np.array([float(xi), float(eta)])
        return float(dx + self.crpix[0]), float(dy + self.crpix[1])

    def pixel_to_sky(self, x, y):
        xi, eta = self.cd @ np.array([x - self.crpix[0], y - self.crpix[1]])
        ra, dec = inverse_gnomonic(xi, eta, *self.crval)
        return float(ra), float(dec)

    def pixel_scale_arcsec(self):
        return self.scale_arcsec, self.scale_arcsec

    def wavelength_at(self, x, y):
        return self.wl0 + self.wls * x, self.bw

    def add_star(self, ra, dec, peak_mjysr, sigma_px=0.9):
        x0, y0 = self.sky_to_pixel(ra, dec)
        yy, xx = np.indices(self.shape)
        self.image += peak_mjysr * np.exp(-0.5 * ((xx - x0) ** 2 + (yy - y0) ** 2) / sigma_px ** 2)
        return x0, y0

    def finalize(self):
        """Add Poisson-like noise consistent with VARIANCE (variance grows with signal)."""
        self.variance = self.noise ** 2 + 0.002 * np.clip(self.image, 0, None)
        self.image = self.image + self.rng.normal(0, np.sqrt(self.variance))
        return self
